changes.content:
types:
  retro_board:
    fields:
      id: { kind: string, required: true }
      name: { kind: string, required: true }
      description: { kind: string, required: true }
      isLocked: { kind: enum, values: ["true", "false"], required: true }
  retro_column:
    fields:
      id: { kind: string, required: true }
      board_id: { kind: string, required: true }
      name: { kind: string, required: true }
      description: { kind: string, required: true }
      color: { kind: string, required: true }
      index: { kind: number, required: true }
      visible: { kind: enum, values: ["true", "false"], required: true }
  retro_note:
    fields:
      id: { kind: string, required: true }
      board_id: { kind: string, required: true }
      text: { kind: string, required: true }
      column_id: { kind: string, required: true }
      stack_id: { kind: string }
      rank: { kind: number, required: true }
      edited: { kind: enum, values: ["true", "false"], required: true }
      votes: { kind: number, required: true }
  retro_vote:
    fields:
      id: { kind: string, required: true }
      board_id: { kind: string, required: true }
      note_id: { kind: string, required: true }
